// catalog · кейсы cat-16, cat-17, cat-19 (.qa/tests/catalog/) — «קטגוריות»: «מחיקה» недоступна, пока счётчики товаров не загружены (#19daa080);
// сбой загрузки счётчиков — видимое сообщение и «נסה שוב» (#133950be); склонение счётчика «מוצר אחד» (#6fcb020f).
// Только чтение: открываются только меню «פעולות» и закрываются Escape; любые записи в Supabase абортируются.
// Счётчики «N מוצרים» строятся из GET rest/v1/products на этой странице — задерживаем / обрываем только его.
// Блокировка на сервере (DELETE → 400 CATEGORY_HAS_PRODUCTS) — на своих QA-данных в catalog-lifecycle.spec.ts.
import { test, expect, Page, Route } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

const PRODUCTS = /\/rest\/v1\/products\?/;
const rows = (page: Page) => page.getByRole('main').getByRole('button', { name: /^שינוי סדר — / });
const menuOfFirst = (page: Page) => page.getByRole('main').getByRole('button', { name: 'פעולות' }).first();

async function guardWrites(page: Page) {
  const violations: string[] = [];
  await page.route(/supabase\.co\/rest\/v1\//, (route: Route) => {
    const r = route.request();
    if (['GET', 'HEAD', 'OPTIONS'].includes(r.method())) return route.fallback();
    violations.push(`${r.method()} ${r.url()}`);
    return route.abort();
  });
  return violations;
}

test.describe('catalog — קטגוריות: מחיקה רק אחרי טעינת מוני המוצרים (#19daa080)', () => {
  let violations: string[] = [];
  test.beforeEach(async ({ page }) => { violations = await guardWrites(page); });
  test.afterEach(() => { expect(violations, 'страница категорий не должна ничего записывать').toEqual([]); });

  test('בזמן טעינת המונים: «טוען…» במקום «0 מוצרים», «מחיקה» לא זמינה; אחרי הטעינה — «מכיל מוצרים» חסום #19daa080 @prod-safe', async ({ page }) => {
    await page.route(PRODUCTS, async (route) => {
      await new Promise((r) => setTimeout(r, 8_000));
      await route.fallback().catch(() => {});
    });
    await page.goto('/catalog/categories');
    await expect(page.getByRole('heading', { level: 1, name: 'קטגוריות' })).toBeVisible({ timeout: 20_000 });
    await expect(rows(page).first()).toBeVisible({ timeout: 20_000 });
    const main = page.getByRole('main');
    await expect(main.getByRole('status', { name: 'טוען…' }).first()).toBeVisible();
    await expect(main.getByText(/^0 מוצרים$/)).toHaveCount(0);

    await menuOfFirst(page).click();
    const del = page.getByRole('menuitem', { name: /^מחיקה/ });
    await expect(del).toBeDisabled();
    await expect(del).toContainText('טוען…');
    await page.keyboard.press('Escape');

    // после загрузки — реальные счётчики; категория с товарами — «מכיל מוצרים», недоступно
    await expect(main.getByRole('status', { name: 'טוען…' })).toHaveCount(0, { timeout: 30_000 });
    const withProducts = main.getByText(/^[1-9]\d* מוצרים$/).first();
    await expect(withProducts).toBeVisible();
    const row = withProducts.locator('xpath=ancestor::*[.//button[@aria-label="פעולות"]][1]');
    await row.getByRole('button', { name: 'פעולות' }).click();
    await expect(del).toBeDisabled();
    await expect(del).toContainText('מכיל מוצרים');
    await page.keyboard.press('Escape');
  });

  test('כשל בטעינת המונים: «מחיקה» לא זמינה עם «לא ניתן לבדוק את המוצרים», בלי «0 מוצרים»; הודעת שגיאה עם «נסה שוב» #19daa080 #133950be @desktop @prod-safe', async ({ page }) => {
    test.setTimeout(90_000);
    await page.route(PRODUCTS, (route) => route.abort());
    await page.goto('/catalog/categories');
    await expect(rows(page).first()).toBeVisible({ timeout: 20_000 });
    const main = page.getByRole('main');
    // приложение повторяет запрос (~15 с); затем счётчик — «—», удаление по-прежнему недоступно
    await expect(main.getByRole('status', { name: 'טוען…' })).toHaveCount(0, { timeout: 45_000 });
    await expect(main.getByText(/^0 מוצרים$/)).toHaveCount(0);
    // #133950be: причина видна не только в title — сообщение и «נסה שוב»
    const alert = page.getByRole('alert').filter({ hasText: ERR_TEXT });
    await expect(alert).toBeVisible();
    await expect(alert.getByRole('button', { name: 'נסה שוב' })).toBeVisible();
    await menuOfFirst(page).click();
    const del = page.getByRole('menuitem', { name: /^מחיקה/ });
    await expect(del).toBeDisabled();
    await expect(del).toContainText('לא ניתן לבדוק את המוצרים');
    await page.keyboard.press('Escape');
  });
});

// ---- #133950be (2026-10-05, עבר QA): телефон — при сбое запроса счётчиков видимое сообщение + «נסה שוב» ----
const ERR_TEXT = 'אירעה שגיאה בטעינת מספר המוצרים בקטגוריות. נסה שוב.';

test.describe('catalog — קטגוריות בטלפון: כשל בטעינת המונים (#133950be)', () => {
  let violations: string[] = [];
  test.beforeEach(async ({ page }) => { violations = await guardWrites(page); });
  test.afterEach(() => { expect(violations, 'страница категорий не должна ничего записывать').toEqual([]); });

  test('כשל: אחרי הניסיונות — alert «אירעה שגיאה בטעינת מספר המוצרים בקטגוריות. נסה שוב.» ו«נסה שוב»; אחרי חזרת הרשת — המונים נטענים #133950be @mobile @prod-safe', async ({ page }) => {
    test.setTimeout(90_000);
    await page.route(PRODUCTS, (route) => route.abort());
    await page.goto('/catalog/categories');
    await expect(rows(page).first()).toBeVisible({ timeout: 20_000 });
    const main = page.getByRole('main');
    const alert = page.getByRole('alert').filter({ hasText: ERR_TEXT });
    // приложение повторяет запрос ~15–16 с, затем показывает сообщение
    await expect(alert).toBeVisible({ timeout: 45_000 });
    const retry = alert.getByRole('button', { name: 'נסה שוב' });
    await expect(retry).toBeVisible();
    await expect(main.getByText(/^0 מוצרים$/)).toHaveCount(0);
    // текст сообщения не обрезан и без горизонтальной прокрутки страницы
    const clip = await alert.evaluate((el) => ({ sw: el.scrollWidth, cw: el.clientWidth, doc: document.documentElement.scrollWidth, vw: innerWidth }));
    expect(clip.sw).toBeLessThanOrEqual(clip.cw + 1);
    expect(clip.doc).toBeLessThanOrEqual(clip.vw + 1);

    await page.unroute(PRODUCTS);
    await retry.click();
    await expect(main.getByText(/^(\d+ מוצרים|מוצר אחד)$/).first()).toBeVisible({ timeout: 30_000 });
    await expect(alert).toHaveCount(0);
  });

  test('בלי כשל — המונים נטענים, אין הודעת שגיאה #133950be @mobile @prod-safe', async ({ page }) => {
    await page.goto('/catalog/categories');
    await expect(rows(page).first()).toBeVisible({ timeout: 20_000 });
    const main = page.getByRole('main');
    await expect(main.getByRole('status', { name: 'טוען…' })).toHaveCount(0, { timeout: 30_000 });
    await expect(main.getByText(/^(\d+ מוצרים|מוצר אחד)$/).first()).toBeVisible();
    await expect(page.getByText(ERR_TEXT)).toHaveCount(0);
  });
});

// ---- #6fcb020f (2026-10-05, עבר QA): 1 → «מוצר אחד», 2+ → «N מוצרים» ----
test.describe('catalog — קטגוריות: ניסוח המונה (#6fcb020f)', () => {
  test('מונה מוצרים: אין «1 מוצרים» — «מוצר אחד» לקטגוריה עם מוצר יחיד, «N מוצרים» ל-0 ו-2+ #6fcb020f @desktop @prod-safe', async ({ page }) => {
    await guardWrites(page);
    await page.goto('/catalog/categories');
    await expect(rows(page).first()).toBeVisible({ timeout: 20_000 });
    const main = page.getByRole('main');
    await expect(main.getByRole('status', { name: 'טוען…' })).toHaveCount(0, { timeout: 30_000 });
    const counters = await main.getByText(/^(\d+ מוצרים|מוצר אחד)$/).allInnerTexts();
    expect(counters.length).toBeGreaterThan(0);
    for (const c of counters) expect(c.trim(), 'счётчик категории').toMatch(/^(0 מוצרים|מוצר אחד|([2-9]|[1-9]\d+) מוצרים)$/);
    await expect(main.getByText(/^1 מוצרים$/)).toHaveCount(0);
    // на 05.10 «מבחנות» и «אלקטרונית» — по 1 товару («מוצר אחד»); точная проверка «1 → מוצר אחד» на своих данных — catalog-lifecycle.spec.ts
  });
});
